import re

_UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_NUM = r"\d+(?:\.\d+)?"


def _finalize(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(round(total))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("expected a string")
    s = text.strip()
    if not s:
        raise ValueError("empty input")

    # bare integer -> seconds
    if re.fullmatch(r"\d+", s):
        return int(s)

    # clock notation hh:mm:ss or mm:ss
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3) or not all(re.fullmatch(r"\d+", p) for p in parts):
            raise ValueError(f"invalid clock notation: {text!r}")
        nums = [int(p) for p in parts]
        if len(nums) == 2:
            mm, ss = nums
            total = mm * 60 + ss
        else:
            hh, mm, ss = nums
            total = hh * 3600 + mm * 60 + ss
        return _finalize(total)

    # ISO 8601 durations
    if s[0] in "Pp":
        iso = re.fullmatch(
            r"[Pp]"
            rf"(?:({_NUM})[Ww])?"
            rf"(?:({_NUM})[Dd])?"
            rf"(?:[Tt]"
            rf"(?:({_NUM})[Hh])?"
            rf"(?:({_NUM})[Mm])?"
            rf"(?:({_NUM})[Ss])?"
            r")?",
            s,
        )
        if not iso or all(g is None for g in iso.groups()):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        w, d, h, m, sec = iso.groups()
        total = 0.0
        total += float(w) * 604800 if w else 0.0
        total += float(d) * 86400 if d else 0.0
        total += float(h) * 3600 if h else 0.0
        total += float(m) * 60 if m else 0.0
        total += float(sec) if sec else 0.0
        return _finalize(total)

    # number+unit components
    pattern = re.compile(rf"({_NUM})\s*([a-zA-Z]+)")
    pos = 0
    total = 0.0
    matched = False
    for match in pattern.finditer(s):
        # ensure no unexpected characters between matches
        between = s[pos:match.start()]
        if between.strip():
            raise ValueError(f"invalid duration: {text!r}")
        unit = match.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit: {unit!r}")
        total += float(match.group(1)) * _UNITS[unit]
        pos = match.end()
        matched = True

    if not matched or s[pos:].strip():
        raise ValueError(f"invalid duration: {text!r}")

    return _finalize(total)

